tw.local.actions =[];

/************************************************************************************************************************
/*------------------------------------ Set Action List For Create ODC Process -----------------------------------------
************************************************************************************************************************/
 
tw.local.screenName = tw.epv.ScreenNames.CACT01;
//Set Actions for Act01	
if(tw.local.conditions.screenName == tw.local.screenName){
	if(tw.local.conditions.userRole == tw.epv.userRole.hub)
	{
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.submitRequest+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.submitRequestToHubDirectly+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.cancelRequest+"";
	}
	else if(tw.local.conditions.userRole == tw.epv.userRole.branch)
	{
	 	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.submitRequest+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.cancelRequest+"";
	}
}
tw.local.screenName = tw.epv.ScreenNames.CACT02 + "";
//Set Actions for Act02
if(tw.local.conditions.screenName == tw.local.screenName){
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.cancelRequest)
	{
	 	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.cancelRequest+"";
		
	}
	else
	{
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.approveRequest+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.ObtainComplianceDepartmentApproval+"";
	}
 }
tw.local.screenName = tw.epv.ScreenNames.CACT03;
//Set Actions for Act03
if(tw.local.conditions.screenName == tw.local.screenName) 
{
	if(tw.local.conditions.complianceApproval){
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.obtainApprovals+"";
	}
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.approveRequest+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.terminateRequest+""; 

}

tw.local.screenName = tw.epv.ScreenNames.CACT04;
//Set Actions for Act04

if(tw.local.conditions.screenName == tw.local.screenName)
{
	if(tw.local.conditions.complianceApproval == true)
	{
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.obtainApprovals+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToTradeFo+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.terminateRequest+"";
	}
	else
	{
	if(tw.local.conditions.requestType == tw.epv.RequestType.Create)
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.createContract+"";
	
	if(tw.local.conditions.requestType == tw.epv.RequestType.Amendment)
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.amendContract+"";	
	
	if(tw.local.conditions.requestType == tw.epv.RequestType.Recreate)
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.recreateContract+"";
	
	if(tw.local.conditions.submiteToHub==true){
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
	}
	else{
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToTradeFo+"";
	}
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.terminateRequest+"";
	}
}

tw.local.screenName = tw.epv.ScreenNames.CACT05;
//Set Actions for Act05
if(tw.local.conditions.screenName == tw.local.screenName)
{
	if(tw.local.conditions.complianceApproval == true)
	{
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.obtainApprovals+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToMaker+"";
	}

	else if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.returnToTradeFo)
	{
	
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToTradeFo+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToMaker+"";
	
	}
	else if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.terminateRequest)
	{
	
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.terminateRequest+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToMaker+"";
	
	}
	else if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.returnToInitiator){
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToMaker+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
	}
	else 
	{
	
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.authorize+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToMaker+"";
	
	}
}
tw.local.screenName = tw.epv.ScreenNames.CACT06;
//Set Actions for Act06
if(tw.local.conditions.screenName == tw.local.screenName){
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.completeRequest+"";
}
//Set Actions for ACT07 // Subprocess unified trade FO subprocess


tw.local.screenName = tw.epv.ScreenNames.CACT07;
if(tw.local.conditions.screenName == tw.local.screenName){

	tw.local.actions[tw.local.actions.listLength] =tw.epv.CreationActions.approveRequest+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToRequester+"";
}



/************************************************************************************************************************
/*------------------------------------ Set Action List For Collection ODC Process ---------------------------------------
************************************************************************************************************************/
//screen01
if(tw.local.conditions.screenName == (tw.epv.Col_ScreenNames.ODCCol01+"") ){
	
	tw.local.actions[tw.local.actions.listLength] = tw.epv.Col_Actions.createLiq+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.Col_Actions.cancel+"";
}
//screen02
if(tw.local.conditions.screenName == (tw.epv.Col_ScreenNames.ODCCol02+"") ){
	
	if(tw.local.conditions.subStatus=="Pending Execution Hub Liquidation Review")
		tw.local.actions[tw.local.actions.listLength] = tw.epv.Col_Actions.authorize+"";
	
	tw.local.actions[tw.local.actions.listLength] = tw.epv.Col_Actions.returnToMaker+"";

	if(tw.local.conditions.subStatus=="Pending Cancelation Confirmation")
		tw.local.actions[tw.local.actions.listLength] = tw.epv.Col_Actions.cancel+"";
}
/************************************************************************************************************************
/*------------------------------------ Set Action List For Reversal ODC Process ---------------------------------------
************************************************************************************************************************/ 
tw.local.screenName = tw.epv.ScreenNames.RACT01;
//Set Actions for Act01	
if(tw.local.conditions.screenName == tw.local.screenName){
	
	 	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.submitRequest+"";
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.cancelRequest+"";
}	
///Set actions for reversal act2
if(tw.local.conditions.screenName == tw.epv.ScreenNames.RACT02 )
{
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.cancelRequest)
	{
	
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToInitiator+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.cancelRequest+"";
	}
	else
	{
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.approveRequest+"";
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToInitiator+"";
	}
}










/************************************************************************************************************************
/*------------------------------------ Set Action List For closure ODC Process ---------------------------------------
************************************************************************************************************************/ 
tw.local.screenName = tw.epv.ScreenNames.closureACT01;
if(tw.local.screenName == tw.local.conditions.screenName)
{
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.submitRequest+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.submitRequestToHubDirectly+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.cancelRequest+"";
}

tw.local.screenName = tw.epv.ScreenNames.closureACT02+"";
if(tw.local.screenName == tw.local.conditions.screenName)
{
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.cancelRequest)
	{
	
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToInitiator+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.cancelRequest+"";
	}
	else
	{
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.approveRequest+"";
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToInitiator+"";
		
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.ObtainComplianceDepartmentApproval+"";
		
	}
}
tw.local.screenName = tw.epv.ScreenNames.closureACT03;
if(tw.local.screenName == tw.local.conditions.screenName)
{
	
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.approveRequest+"";
	
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToInitiator+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.terminateRequest+"";
}
tw.local.screenName = tw.epv.ScreenNames.closureACT04;
if(tw.local.screenName == tw.local.conditions.screenName)
{
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.terminateRequest)
	{
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToMaker+"";
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.terminateRequest+"";
	}
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.returnToInitiator)
	{
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToMaker+"";
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToInitiator+"";
	}
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.approveRequest)
	{
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.approveRequest+"";
		tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToMaker+"";
	}
	
}

tw.local.screenName = tw.epv.ScreenNames.closureACT05+"";
if(tw.local.screenName == tw.local.conditions.screenName)
{
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.approveRequest+"";
	if(tw.local.conditions.submiteToHub==true){
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
	}
	else{
		tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToTradeFo+"";
	}
	//tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToTradeFo+"";
}
tw.local.screenName = tw.epv.ScreenNames.closureACT06;
if(tw.local.screenName == tw.local.conditions.screenName)
{
	
	
	
	if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.returnToTradeFo)
	{
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToTradeFo+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToMaker+"";
	}
	else if(tw.local.conditions.lastStepAction == tw.epv.CreationActions.returnToInitiator ){
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToMaker+"";
	tw.local.actions[tw.local.actions.listLength]= tw.epv.CreationActions.returnToInitiator+"";
	}
	else
	{
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.approveRequest+"";
	tw.local.actions[tw.local.actions.listLength] = tw.epv.CreationActions.returnToMaker+"";
	}
}


















