"}]},"declaredType":"errorEventDefinition","id":"c3519752-aad0-4434-83fd-51d46a1a0e86","otherAttributes":{"eventImplId":"68d43d02-3e62-4279-85a4-2da6444a99ff"}}],"extensionElements":{"nodeVisualInfo":[{"width":24,"x":369,"y":299,"declaredType":"TNodeVisualInfo","height":24}]},"name":"Error Event","declaredType":"intermediateCatchEvent","id":"dcc87a3a-3709-495f-8fd9-274ad78eacc4"},{"targetRef":"c0fca24a-76a7-443f-87d8-57a34ee000bf","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Exception Handling","declaredType":"sequenceFlow","id":"3391f2d4-608a-4759-8695-e56bcdc5b497","sourceRef":"dcc87a3a-3709-495f-8fd9-274ad78eacc4"},{"targetRef":"09e628df-d4ba-408b-b61b-83722a082cca","extensionElements":{"sequenceFlowImplementation":[{"fireValidation":"Never","sboSyncEnabled":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TSequenceFlowImplementation"}],"endStateId":["guid:f6ffc3b64be5dfa5:4157166b:18ab80e0606:-6f83"],"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":true,"showLabel":false}]},"name":"To End Event","declaredType":"sequenceFlow","id":"decbc7eb-859e-472d-896f-80a406c95d14","sourceRef":"c0fca24a-76a7-443f-87d8-57a34ee000bf"}],"laneSet":[{"id":"19ff87d9-a521-48dc-8e53-589a83bbdd2e","lane":[{"flowNodeRef":["41718139-7b6e-4468-8396-607a3e22495d","73414ba8-e14a-4008-86f8-697d960a169b","09e628df-d4ba-408b-b61b-83722a082cca","f64b170f-b2e6-479e-8608-f1058c6779f1","48939383-8428-43f2-8589-85728a5dc2f7","eb1dae19-eaa0-4a23-8299-7a66ae48caec","c0fca24a-76a7-443f-87d8-57a34ee000bf","dcc87a3a-3709-495f-8fd9-274ad78eacc4"],"extensionElements":{"nodeVisualInfo":[{"color":"#F8F8F8","width":3000,"x":0,"y":0,"declaredType":"TNodeV