ype":"com.ibm.bpmsdk.model.bpmn20.ibmext.TEpvProcessLinks"}]},"inputSet":[{"dataInputRefs":["2055.dab3e84e-2056-4fcc-8ee5-0748f03cbf1d"]}],"outputSet":[{"dataOutputRefs":["2055.23dbb134-6c18-443b-b36d-def23540d7d8"]}],"dataInput":[{"extensionElements":{"defaultValue":[{"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmext.TDefaultValue","useDefault":false,"value":"undefined"}]},"itemSubjectRef":"itm.12.c09c9b6e-aabd-4897-bef2-ed61db106297","documentation":[{"content":["//&quot;screenName,userRole,complianceApproval,lastAction&quot;"],"textFormat":"text/plain"}],"name":"data","isCollection":false,"id":"2055.dab3e84e-2056-4fcc-8ee5-0748f03cbf1d"}]}}],"targetNamespace":"","typeLanguage":"http://www.w3.org/2001/XMLSchema","expressionLanguage":"http://www.ibm.com/xmlns/prod/bpm/expression-lang/javascript"}

